-- 本界面 是否从 好友聊天系统而来
function Player2DOptionBtns:IsFromFriendChat()
    return isNotNull(self.exParameter) and self.exParameter.chatEnter == true
end



function Player2DOptionBtns:IsFromClub()
    return isNotNull(self.exParameter) and self.exParameter.enterType == "Club"
end



return Player2DOptionBtns
